def parcel_cost(cart) -> int:
    total_weight = 0
    for item in cart:
        if 'grams' in item and not item.get('digital', False):
            total_weight += item['qty'] * item['grams']
    if total_weight <= 500:
        return 399
    elif total_weight <= 2000:
        return 750
    elif total_weight <= 10000:
        return 1200
    else:
        weight_above = total_weight - 10000
        num_units = (weight_above + 999) // 1000  # Rounding up
        return 1200 + num_units * 150
