def mileage_claim(trips) -> int:
    total = 0
    for trip in trips:
        if trip['km'] is None:
            trip['km'] = 0
        rounded_km = ((trip['km'] + 4) // 5) * 5  # Round up to nearest 5 km
        total += rounded_km * 45
    return total
