def share_bill(items, people, tip_pct) -> dict:
    person_shares = {person: 0 for person in people}
    for item in items:
        if item['eaters']:
            for eater in item['eaters']:
                if eater in person_shares:
                    person_shares[eater] += item['price'] / len(item['eaters'])
        else:
            for person in people:
                person_shares[person] += item['price'] / len(people)
    base_total = sum(person_shares.values())
    tip_total = base_total * (tip_pct / 100)
    for person in people:
        base = person_shares[person]
        tip = (base / base_total) * tip_total
        person_shares[person] = round(base + tip)
    return person_shares
