def pick_next(history, library):
    if not library:
        return None
    if not history:
        return library[0]['id']
    last_id = history[-1]
    last_song = None
    for song in library:
        if song['id'] == last_id:
            last_song = song
            break
    if last_song is not None:
        current_bpm = last_song['bpm']
        tolerance = 5
        candidates = [s for s in library if s['id'] != last_id and abs(s['bpm'] - current_bpm) <= tolerance]
        if candidates:
            candidates.sort(key=lambda x: (-x['bpm'], -x['id']))
            return candidates[0]['id']
        else:
            closest = None
            for song in library:
                if song['id'] == last_id:
                    continue
                diff = abs(song['bpm'] - current_bpm)
                if closest is None or diff < closest['diff'] or (diff == closest['diff'] and song['bpm'] > closest['song']['bpm']):
                    closest = {'song': song, 'diff': diff}
            if closest is not None:
                return closest['song']['id']
            else:
                return library[0]['id'] if library else None
    else:
