def blend(a, b, overlap):
    if not a or not b:
        return []
    n = min(overlap, len(a), len(b))
    output = a[:len(a) - n]
    for i in range(n):
        output.append((a[len(a) - n + i] + b[i]) / 2.0)
    output.extend(b[n:])
    return output
