def due_doses(meds, taken, now, tz):
    from datetime import datetime, timedelta

    # Convert now to local time by adding tz minutes
    now_local = now + timedelta(minutes=tz)

    # Determine the start of the current week (Monday 00:00 UTC)
    week_start = datetime.strptime(now_local.strftime("%d/%m/%Y"), "%d/%m/%Y") - timedelta(days=now_local.weekday())
    week_start = week_start.replace(hour=0, minute=0, second=0, microsecond=0)

    # Calculate the start and end of the current local day in UTC
    current_local_day_start_utc = week_start + timedelta(minutes=tz)
    current_local_day_end_utc = current_local_day_start_utc + timedelta(minutes=1440)

    # Filter doses scheduled on the current local day
    current_doses = []
    for med in meds:
        for dose in med['times']:
            dose_utc = week_start + timedelta(minutes=dose)
            if dose_utc >= current_local_day_start_utc and dose_utc < current_local_day_end_utc:
                current_doses.append({'med': med['name'], 'time': dose})

    # Check which doses have not been taken
    due_doses = []
    for dose in current_doses:
        taken_today = False
        for taken_entry in taken:
            if taken_entry['med'] == dose['med'] and taken_entry['at'] == dose['time']:
                taken_utc = week_start + timedelta(minutes=taken_entry['at'])
                if taken_utc >= current_local_day_start_utc and taken_utc < current_local_day_end_utc:
                    taken_today = True
                    break
        if not taken_today:
            due_doses.append(dose)

    # Sort by time (ascending), then by medicine name (alphabetically)
    due_doses.sort(key=lambda x: (x['time'], x['med']))
    return due_doses
